<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;
final class OperationalAnalyticsView
{
    private static function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
    private static function table(string $caption,array $headers,array $rows):string{$x='<div class="analytics-scroll" tabindex="0" role="region" aria-label="'.self::h($caption).'"><table><caption>'.self::h($caption).'</caption><thead><tr>';foreach($headers as $head)$x.='<th scope="col">'.self::h($head).'</th>';$x.='</tr></thead><tbody>';foreach($rows as $row){$x.='<tr>';foreach($row as $v)$x.='<td>'.self::h($v).'</td>';$x.='</tr>';}$x.='</tbody></table></div>';if(!$rows)$x.='<p class="analytics-empty">No eligible records in this scope. This does not establish historical activity outside the selected period.</p>';return $x;}
    public static function render(array $d):string{
        $h=static fn($v)=>self::h($v);$query=['analytics'=>'1','merchant'=>$d['merchant'],'outlet'=>$d['outlet'],'from'=>$d['from'],'to'=>$d['to'],'station'=>$d['station']];$url='/merchant.php?'.http_build_query($query);$x='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operational analytics · KIOS</title><link rel="stylesheet" href="/assets/merchant-setup.css"><link rel="stylesheet" href="/assets/operational-analytics.css"><script src="/assets/operational-analytics.js" defer></script></head><body><main data-analytics data-merchant="'.$h($d['merchant']).'" data-outlet="'.$h($d['selected'][0]['outlet_id']).'"><header><div><p class="eyebrow">Operational intelligence · Private synthetic demonstration</p><h1>Operational analytics</h1><p>Actual service, kitchen, seating and stock records. No sales, revenue or profit estimates.</p></div></header><form method="get" data-analytics-filter><input type="hidden" name="analytics" value="1"><input type="hidden" name="merchant" value="'.$h($d['merchant']).'"><label>Outlet<select name="outlet">';
        if($d['canAggregate'])$x.='<option value="all"'.($d['outlet']==='all'?' selected':'').'>All merchant outlets · owner only</option>';foreach($d['outlets']as $o)$x.='<option value="'.$h($o['outlet_id']).'"'.($o['outlet_id']===$d['outlet']?' selected':'').'>'.$h($o['name']).'</option>';$x.='</select></label><label>From · UTC<input type="date" name="from" value="'.$h($d['from']).'" required></label><label>Through · UTC<input type="date" name="to" value="'.$h($d['to']).'" required></label><label>Kitchen station<select name="station"><option value="">All authorized stations</option>';foreach($d['stations']as $station)$x.='<option value="'.$station['station_id'].'"'.((string)$station['station_id']===$d['station']?' selected':'').'>'.$h($station['name']).'</option>';$x.='</select></label><button>Apply filters</button></form><p role="status" data-analytics-loading>Read-only snapshot as of '.gmdate('Y-m-d H:i:s',$d['asOf']).' UTC. Up to 31 inclusive days. Station filter affects kitchen task measures only.</p><nav class="analytics-nav" aria-label="Analytics sections">';foreach(['overview'=>'Executive overview','kitchen'=>'Kitchen','seating'=>'Seating','inventory'=>'Inventory','staff'=>'Staff activity','reports'=>'Report centre']as $id=>$label)$x.='<a href="#'.$id.'">'.$label.'</a>';$x.='</nav><section class="panel" id="overview"><h2>Executive overview</h2><div class="analytics-metrics">';$totals=[];foreach($d['metrics']as $m){$totals[$m[1]]['value']=($totals[$m[1]]['value']??0)+$m[2];$totals[$m[1]]['scope']=$m[3];}foreach($totals as $label=>$v)$x.='<article><span>'.$h($label).'</span><strong>'.$v['value'].'</strong><small>'.$h($v['scope']).'</small></article>';$x.='</div><details><summary>Outlet drilldown</summary>'.self::table('Operational counts; no financial values',['Outlet','Metric','Count','Eligibility'],$d['metrics']).'</details></section><section class="panel" id="kitchen"><h2>Kitchen analytics</h2><p>Task-created cohort in the UTC period. Durations use actual preparing → ready events, not order age. Incomplete and invalid pairs never enter the average.</p>'.self::table('Station preparation workload and timing',['Outlet','Station','Tasks','Queued','Preparing','Ready','Mean seconds','Valid pairs','Incomplete','Invalid'],$d['kitchen']);
        $timings=[];foreach($d['export']as $r)if(in_array($r[0],['kitchen','seating'],true)&&$r[4]==='seconds')$timings[]=[$r[1],$r[2],$r[3],$r[5]];$x.=self::table('Paired event duration definitions and denominators',['Outlet','Measure','Seconds','Cohort / denominator'],$timings).'</section><section class="panel" id="seating"><h2>Tables & reservations</h2><p>Tables are the current recorded active-table state, independent of date filters. Reservation counts are unique records created during the period, grouped by their current state. These are not reconstructed historical occupancy.</p>'.self::table('Current active tables',['Outlet','State','Tables'],$d['seating']).'<div class="analytics-bars">';$max=max([1,...array_column($d['reservations'],2)]);foreach($d['reservations']as $v)$x.='<label>'.$h($v[0].' · '.$v[1]).' <strong>'.$v[2].'</strong><meter min="0" max="'.$max.'" value="'.$v[2].'">'.$v[2].'</meter></label>';$x.='</div>'.self::table('Reservation creation cohort, current lifecycle',['Outlet','State','Reservations'],$d['reservations']).'</section><section class="panel" id="inventory"><h2>Inventory intelligence</h2><p>Current balances reconcile against the complete signed ledger. Movement tables and trends use the selected UTC period. Native units stay separate; recipes never imply consumption. Reversals are shown separately with their original operation.</p>';
        $stock=[];foreach($d['inventory']as $row){$row[3]/=1000;$row[4]/=1000;$stock[]=$row;}$x.=self::table('Current stock and independent ledger reconciliation',['Outlet','Item','Unit','Balance','Minimum','Status','Reconciled'],$stock).self::table('Recorded signed movement, including opening stock and reversals',['Outlet','Operation','Unit','Signed delta','Movement rows'],$d['movements']).self::table('Actual daily signed stock movement',['Outlet','UTC day','Unit','Signed delta'],$d['trends']).'</section><section class="panel" id="staff"><h2>Authorized staff activity</h2><p>Audit-event counts only. Actor references contain no passwords, guest names, attendance or productivity estimates. Kitchen transition events are counted once; their authorization guard audit is not counted again.</p><label>Search this activity page<input type="search" data-analytics-search></label>';
        $x.=self::table('Activity groups, 25 per page',['Outlet','Source','Actor reference','Action','Events'],$d['activity']).'<p>Page '.$d['page'].' · '.$d['activityTotal'].' groups in scope.</p><nav aria-label="Activity pages">';if($d['page']>1)$x.='<a href="'.$h($url.'&page='.($d['page']-1)).'#staff">Previous</a> ';if($d['page']*25<$d['activityTotal'])$x.='<a href="'.$h($url.'&page='.($d['page']+1)).'#staff">Next</a>';$x.='</nav></section><section class="panel" id="reports"><h2>Report centre & data quality</h2><a class="analytics-export" href="'.$h($url.'&export=csv').'">Download authorized CSV</a><p>Export includes all eligible activity groups, not just the visible page. It uses the same definitions, date range and authorized outlet scope. Current-state rows are explicitly labelled; unavailable timing measures remain unavailable.</p><ul>';foreach(array_unique($d['quality'])as $q)$x.='<li>'.$h($q).'</li>';$x.='</ul><details><summary>Metric definitions</summary><p>Service creation: distinct service sessions by created epoch. Submissions/completions: distinct service IDs in submit/served audit events in range. Current queued/ready orders: active SUBMITTED services, distinct order IDs. Preparation average: sum of valid paired seconds / valid task pairs. Ready wait: actual ready history → served audit event. Reservation seated episodes: one SEATED and one COMPLETED audit event, completed in range; table transfers remain within the reservation episode. Manual occupancy duration is unavailable. Inventory balances: current items versus all signed ledger deltas; movement deltas: actual dated movement rows, per native unit. Activity: authoritative per-source audit groups, no financial or employee-performance inference.</p></details></section></main></body></html>';return $x;
    }
}
